import { X509Certificate } from "node:crypto";

// Synthetic automated-test material only; never install or use for deployment.
function testCertificate(certificate: string, pfx: string) {
  return Object.freeze({
    ca: new X509Certificate(Buffer.from(certificate, "base64")).toString(),
    pfx: Buffer.from(pfx, "base64"),
  });
}

export const tlsTestCertificates = Object.freeze({
  localhost: testCertificate(
    "",
    "",
  ),
  wrongName: testCertificate(
    "",
    "",
  ),
  expired: testCertificate(
    "",
    "",
  ),
});
